import { useEffect, useState } from "react";

export default function Books() {
  const [books, setBooks] = useState([]);

  useEffect(() => {
    fetch("http://localhost:5000/books")
      .then(res => res.json())
      .then(data => setBooks(data));
  }, []);

  return (
    <div className="card">
      <h2>Books</h2>

      {books.map((b, i) => (
        <div key={i} className="book-item">
          📘 {b.title}
        </div>
      ))}
    </div>
  );
}
